{"code": "from itertools import permutations
import random

DIAMOND = [(0, 2), (1, 1), (1, 2), (1, 3), (2, 0), (2, 1), (2, 3), (2, 4), (3, 1), (3, 2), (3, 3), (4, 2)]
LEG = DIAMOND + [(2, 2)]
SQUARE = [(r, c) for r in range(5) for c in range(5) if (r, c) not in ((0, 0), (0, 4), (4, 0), (4, 4))]
RING = [(0, 2), (0, 4), (1, 1), (1, 5), (2, 0), (2, 6), (4, 0), (4, 6), (5, 1), (5, 5), (6, 2), (6, 4)]
FILL = [(r, c) for r in range(7) for c in range(7) if abs(r - 3) + abs(c - 3) <= 4]   # ring and its inside
EDGE = "BgSw"

def cells(pos, mask):
    return {(pos[0] + a, pos[1] + b) for a, b in mask}

def find_legs(board):
    # 5x5 diamonds of white (selected) or dark grey, with a coloured centre
    out = []
    for r in range(60):
        for c in range(1, 60):
            ring = {board[r + a][c + b] for a, b in DIAMOND}
            if len(ring) == 1 and ring <= {"W", "G"} and board[r + 2][c + 2] not in "WGBgwS":
                out.append({"r": r, "c": c, "mark": board[r + 2][c + 2], "sel": ring == {"W"}})
    return out

def find_rings(board):
    out = []
    for r in range(58):
        for c in range(1, 58):
            cols = [board[r + a][c + b] for a, b in RING]
            if any(x in "BgwWG" for x in cols) or set(cols) == {"S"}:
                continue
            if board[r + 3][c + 3] in "BSw" and board[r][c] in EDGE:
                out.append({"r": r, "c": c, "colours": set(cols)})
    return out

def find_squares(board, legs):
    near = {(l["r"] + a, l["c"] + b) for l in legs for a in range(5) for b in range(5)}
    out = []
    for r in range(60):
        for c in range(1, 60):
            cols = [board[r + a][c + b] for a, b in SQUARE]
            if any(x in "Bgw" for x in cols) or set(cols) == {"S"}:
                continue
            if any((r + a, c + b) in near for a, b in SQUARE):
                continue
            if board[r][c] not in EDGE or board[r][c + 4] not in EDGE:
                continue
            out.append({"r": r, "c": c, "cells": {(a, b): board[r + a][c + b] for a, b in SQUARE}})
    return out

def body_at(legs):
    n = len(legs)
    return (sum(l["r"] + 2 for l in legs) // n - 2, sum(l["c"] + 2 for l in legs) // n - 2)

def subsets(ids, k):
    if k == 0:
        yield ()
        return
    for i in range(len(ids)):
        for rest in subsets(ids[i + 1:], k - 1):
            yield (ids[i],) + rest

class Scene:
    def __init__(self, board):
        self.walls = {(r, c) for r in range(64) for c in range(64) if board[r][c] == "g"}
        legs = find_legs(board)
        self.rings = find_rings(board)
        squares = find_squares(board, legs)
        self.legs = [{"id": i, "r": l["r"], "c": l["c"], "mark": l["mark"]} for i, l in enumerate(legs)]
        self.sel = next((i for i, l in enumerate(legs) if l["sel"]), None)
        self.groups, used = [], set()
        by_mark = {}
        for l in self.legs:
            by_mark.setdefault(l["mark"], []).append(l["id"])
        for mark, ids in by_mark.items():
            for k in range(len(ids), 0, -1):
                for sub in subsets(ids, k):
                    if used & set(sub):
                        continue
                    b = body_at([self.legs[i] for i in sub])
                    sq = next((s for s in squares if (s["r"], s["c"]) == b), None)
                    if sq is not None and all(sq is not g["sq"] for g in self.groups):
                        self.groups.append({"legs": list(sub), "sq": sq, "paint": dict(sq["cells"])})
                        used.update(sub)
        self.pots = [s for s in squares if all(s is not g["sq"] for g in self.groups)]
        for g in self.groups:
            g["colours"] = set(g["paint"].values()) - {"M", "W"}

def leg_ok(sc, legs, i, r, c):
    if r < 0 or c < 1 or r + 4 > 63 or c + 4 > 63:
        return False
    if cells((r, c), LEG) & sc.walls:
        return False
    if abs(legs[i]["r"] - r) < 5 and abs(legs[i]["c"] - c) < 5:
        return False                                   # the click would land on the handle itself
    return all(l["id"] == i or abs(l["r"] - r) >= 5 or abs(l["c"] - c) >= 5 for l in legs)

def body_ok(sc, pos, allow_pot=None):
    return True                                        # nothing to avoid seen yet

def touches(pos, ring):
    return bool(cells(pos, SQUARE) & cells((ring["r"], ring["c"]), FILL))

def moves_to(sc, legs, group, sel, goals):
    """Fewest clicks so the group's body ends on one of goals (top-left positions)."""
    ids, n = group["legs"], len(group["legs"])
    for i in sorted(ids, key=lambda i: i != sel):     # one handle, the selected one first
        others = [legs[j] for j in ids if j != i]
        sr, sc_ = sum(l["r"] + 2 for l in others), sum(l["c"] + 2 for l in others)
        for br, bc in goals:
            for cr in range(n * (br + 2) - sr, n * (br + 2) - sr + n):
                for cc in range(n * (bc + 2) - sc_, n * (bc + 2) - sc_ + n):
                    if leg_ok(sc, legs, i, cr - 2, cc - 2):
                        new = [dict(l) for l in legs]
                        new[i]["r"], new[i]["c"] = cr - 2, cc - 2
                        return ([f"6 {legs[i]['r'] + 2} {legs[i]['c'] + 2}"] if sel != i else []) + [f"6 {cr} {cc}"], new, i
    return spread(sc, legs, group, sel, goals)

def spread(sc, legs, group, sel, goals, tries=400):
    """Move k >= 2 handles: scatter them round the point that gives the goal body; every body on the way must be safe."""
    rnd = random.Random(0)
    ids, n, best = group["legs"], len(group["legs"]), None
    for k in range(2, n + 1):
        for moving in subsets(sorted(ids, key=lambda i: i != sel), k):
            fixed = [legs[j] for j in ids if j not in moving]
            fr, fc = sum(l["r"] + 2 for l in fixed), sum(l["c"] + 2 for l in fixed)
            for br, bc in goals[:: max(1, len(goals) // 12)]:
                tr, tc = n * (br + 2) - fr, n * (bc + 2) - fc
                for _ in range(tries):
                    pts = [(tr // k + rnd.randint(-14, 14), tc // k + rnd.randint(-14, 14)) for _ in range(k - 1)]
                    pts.append((tr - sum(p[0] for p in pts), tc - sum(p[1] for p in pts)))
                    for perm in permutations(range(k)):
                        cur, clicks, s_, ok = [dict(l) for l in legs], [], sel, True
                        for step_no, idx in enumerate(perm):
                            i, (cr, cc) = moving[idx], pts[idx]
                            if not leg_ok(sc, cur, i, cr - 2, cc - 2):
                                ok = False
                                break
                            if s_ != i:
                                clicks.append(f"6 {cur[i]['r'] + 2} {cur[i]['c'] + 2}")
                            clicks.append(f"6 {cr} {cc}")
                            cur[i]["r"], cur[i]["c"], s_ = cr - 2, cc - 2, i
                            if step_no < k - 1 and not body_ok(sc, body_at([cur[j] for j in ids])):
                                ok = False
                                break
                        if ok and body_at([cur[j] for j in ids]) in goals:
                            if best is None or len(clicks) < len(best[0]):
                                best = (clicks, cur, s_)
                            break
                    if best and len(best[0]) <= 2 * k:
                        return best
        if best:
            return best
    return best

def plan(board):
    """Chunks of clicks, one per group, each with the handles and selection the model expects after it."""
    global GROUPS
    sc = Scene(board)
    GROUPS = [g["legs"] for g in sc.groups]
    legs, sel, chunks = [dict(l) for l in sc.legs], sc.sel, []
    for g in sc.groups:
        ring = next((t for t in sc.rings if t["colours"] == g["colours"]), None)
        if ring is None:
            continue
        goals = [(r, c) for r in range(-2, 62) for c in range(-2, 62) if touches((r, c), ring) and body_ok(sc, (r, c))]
        res = moves_to(sc, legs, g, sel, goals)
        if res is None:
            print("no way for the", "".join(sorted(g["colours"])), "body")
            return sc, None
        clicks, legs, sel = res
        chunks.append((clicks, legs, sel))
    return sc, chunks

def disc_there(board, pos):
    return all(0 <= pos[0] + a < 64 and 0 <= pos[1] + b < 64 and board[pos[0] + a][pos[1] + b] not in "Bg"
               for a, b in SQUARE)

async def go(chunks, **memo):
    """Send each group's clicks, then check that every disc is where the model puts it."""
    r = None
    for clicks, legs, sel in chunks:
        r = await act(clicks, quiet=True, **memo)
        memo = {}
        if r.level_up or r.state != "NOT_FINISHED":
            print(clicks, "->", r.lines[-1][:70] if r.lines else r)
            return r
        board = observe().board
        where = [body_at([legs[i] for i in g]) for g in GROUPS]
        missing = [p for p in where if not disc_there(board, p)]
        if missing:
            print("DIFFERS after", clicks, "| no disc at", missing)
            return r
        print(clicks, "-> discs at", where)
    return r

obs = observe()
sc, chunks = plan(obs.board)
print("handles", [(l["r"], l["c"], l["mark"]) for l in sc.legs], "| selected", sc.sel)
print("disc", [(g["sq"]["r"], g["sq"]["c"]) for g in sc.groups], "| ring", [(t["r"], t["c"]) for t in sc.rings])
print("plan", chunks and [c for c, _, _ in chunks])
r = await go(chunks,
             hypotheses=[{"text": H_MOVE, "status": "verified", "evidence": [0]}, {"text": H_MID, "status": "verified", "evidence": [0]}])
print(r)
"}

